public class Main {
    int maxProduct(int[] nums) {
        int best = nums[0];
        int n = nums.length;
        for (int i = 0; i < n; i++) {                             // every possible starting index
            long product = 1;
            for (int j = i; j < n; j++) {                           // extend the subarray one step at a time
                product *= nums[j];
                best = Math.max(best, (int) product);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        int[] nums = {2, 3, -2, 4};
        Main solution = new Main();
        System.out.println(solution.maxProduct(nums));
    }
}

